import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, uniform, vec2, vec3, mix, float, time, smoothstep, abs } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const { Group, Mesh, PlaneGeometry, Color, PointLight, DirectionalLight, DataTexture, RGBAFormat } = THREE;

  // --- spec colors ---
  const colors = config?.colors ?? config?.intent?.visualSpec?.colors ?? {};
  const inkHex = colors.ink ?? '#16161d';
  const paperHex = colors.paper ?? '#e8ecf2';
  const accentHex = colors.accent ?? '#ff2a38';
  const surfaceHex = colors.surface ?? '#0b0b10';

  const ink = new Color(inkHex);
  const paper = new Color(paperHex);
  const accent = new Color(accentHex);
  const surface = new Color(surfaceHex);

  const ink3 = vec3(float(ink.r), float(ink.g), float(ink.b));
  const surf3 = vec3(float(surface.r), float(surface.g), float(surface.b));
  const accent3 = vec3(float(accent.r), float(accent.g), float(accent.b));
  const paper3 = vec3(float(paper.r), float(paper.g), float(paper.b));

  const group = new Group();
  group.name = 'hub-features-divider';

  // --- STAGE: vertical gradient backdrop (never void) ---
  const backdropGeo = new PlaneGeometry(7, 6);
  const backdropMat = new MeshBasicNodeMaterial();
  backdropMat.colorNode = mix(ink3, surf3, uv().y);
  backdropMat.toneMapped = true;
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  group.add(backdrop);

  // --- parallax divider plane (atlas 512x320 -> 1.6 aspect) ---
  const W = 3.0;
  const H = W / 1.6; // 1.875
  const planeGeo = new PlaneGeometry(W, H, 96, 32);

  // texture uniforms with solid placeholders until async load resolves
  const solidInk = new DataTexture(new Uint8Array([
    Math.round(ink.r*255), Math.round(ink.g*255), Math.round(ink.b*255), 255
  ]), 1, 1, RGBAFormat);
  solidInk.needsUpdate = true;
  const solidMid = new DataTexture(new Uint8Array([128, 128, 128, 255]), 1, 1, RGBAFormat);
  solidMid.needsUpdate = true;

  const colorTexUniform = uniform(solidInk);
  const depthTexUniform = uniform(solidMid);

  // cursor (normalized -1..1) and focus (0..1)
  const cursorX = uniform(0.0);
  const cursorY = uniform(0.0);
  const focus = uniform(0.0);
  const dispStrength = uniform(0.13);

  // parallax uv offset for color + depth (subtle)
  const offset = vec2(cursorX.mul(float(0.035)), cursorY.mul(float(0.035)));
  const dispUV = uv().add(offset);

  // gentle idle breathing along displacement
  const breathe = time.mul(float(0.5)).sin().mul(float(0.012));

  const planeMat = new MeshStandardNodeMaterial();
  planeMat.colorNode = texture(colorTexUniform, dispUV).rgb;
  planeMat.roughnessNode = float(0.55);
  planeMat.metalnessNode = float(0.5);
  planeMat.clearcoatNode = float(0.2);
  planeMat.clearcoatRoughnessNode = float(0.5);

  // real vertex displacement via depth map (parallax-plane)
  planeMat.displacementNode = texture(depthTexUniform, dispUV).r
    .mul(dispStrength)
    .add(breathe);

  // accent focus edge glow: edges of plane light up accent on hover
  const edgeField = abs(uv().x.sub(float(0.5))).mul(float(2.0)); // 0 center -> 1 edge
  const edgeGlow = smoothstep(float(0.78), float(1.0), edgeField);
  planeMat.emissiveNode = accent3.mul(focus.mul(edgeGlow).mul(float(0.7)));

  // center jewel emissive read from depth peak (bright middle of rule)
  const jewelRead = smoothstep(float(0.82), float(1.0), texture(depthTexUniform, dispUV).r);
  planeMat.emissiveNode = planeMat.emissiveNode.add(accent3.mul(
    focus.add(float(0.35)).mul(jewelRead).mul(float(0.6))
  ));

  const plane = new Mesh(planeGeo, planeMat);
  plane.renderOrder = 1;
  group.add(plane);

  // --- lighting: rim/accent + back fill (scene already provides ambient 0.6 + key 1.2) ---
  const rimAccent = new PointLight(accent, 1.1, 10, 1.6);
  rimAccent.position.set(-2.2, 1.4, 1.8);
  group.add(rimAccent);

  const rimCool = new PointLight(paper, 0.7, 10, 1.6);
  rimCool.position.set(2.4, -1.0, 1.5);
  group.add(rimCool);

  const back = new DirectionalLight(paper, 0.5);
  back.position.set(0, 0.5, -3);
  group.add(back);

  // jewel glow point light
  const jewelLight = new PointLight(accent, 1.1, 3.0, 2.0);
  jewelLight.position.set(0, 0, 0.18);
  group.add(jewelLight);

  // --- text content: none per spec (divider only) ---

  // --- async texture application ---
  ctx.textureLoader.loadTexture(config.imageUrl || config.imageUrl).then((t) => {
    t.colorSpace = THREE.SRGBColorSpace;
    t.wrapS = t.wrapT = THREE.ClampToEdgeWrapping;
    t.anisotropy = 4;
    t.needsUpdate = true;
    colorTexUniform.value = t;
    planeMat.needsUpdate = true;
  });
  ctx.textureLoader.loadTexture(config.depthMapUrl).then((t) => {
    t.wrapS = t.wrapT = THREE.ClampToEdgeWrapping;
    t.anisotropy = 4;
    t.needsUpdate = true;
    depthTexUniform.value = t;
    planeMat.needsUpdate = true;
  });

  // --- interaction handlers ---
  group.userData.handlers = {
    pointermove: (e) => {
      const local = e.object.worldToLocal(e.point.clone());
      const nx = Math.max(-1, Math.min(1, (local.x / W) * 2));
      const ny = Math.max(-1, Math.min(1, (local.y / H) * 2));
      gsap.to(cursorX, { value: nx, duration: 0.6, ease: 'power2.out', overwrite: 'auto' });
      gsap.to(cursorY, { value: ny, duration: 0.6, ease: 'power2.out', overwrite: 'auto' });
    },
    pointerenter: () => {
      gsap.to(plane.position, { y: 0.15, duration: 0.7, ease: 'power3.out', overwrite: 'auto' });
      gsap.to(focus, { value: 1, duration: 0.45, ease: 'power2.out', overwrite: 'auto' });
      gsap.to(jewelLight, { intensity: 2.2, duration: 0.45, ease: 'power2.out', overwrite: 'auto' });
      gsap.to(rimAccent, { intensity: 1.4, duration: 0.45, ease: 'power2.out', overwrite: 'auto' });
    },
    pointerleave: () => {
      gsap.to(plane.position, { y: 0, duration: 0.55, ease: 'power3.out', overwrite: 'auto' });
      gsap.to(focus, { value: 0, duration: 0.45, ease: 'power2.out', overwrite: 'auto' });
      gsap.to(jewelLight, { intensity: 1.1, duration: 0.45, ease: 'power2.out', overwrite: 'auto' });
      gsap.to(rimAccent, { intensity: 1.1, duration: 0.45, ease: 'power2.out', overwrite: 'auto' });
      gsap.to(cursorX, { value: 0, duration: 0.8, ease: 'power2.out', overwrite: 'auto' });
      gsap.to(cursorY, { value: 0, duration: 0.8, ease: 'power2.out', overwrite: 'auto' });
    },
    click: () => {
      const press = gsap.timeline();
      press
        .to(plane.scale, { x: 0.97, y: 0.97, duration: 0.12, ease: 'back.out(2)' })
        .to(plane.scale, { x: 1.0, y: 1.0, duration: 0.36, ease: 'power4.out' }, '+=0.0')
        .to(jewelLight, { intensity: 2.6, duration: 0.12, yoyo: true, repeat: 1 }, 0)
        .eventCallback('onComplete', () => {
          ctx.emit('navigate', { to: 'hub-features' });
          ctx.emit('hub-features.select', { source: 'features-divider' });
        });
      pressPings.push(press);
    },
    focus: () => {
      gsap.to(focus, { value: 1, duration: 0.4, ease: 'power2.out', overwrite: 'auto' });
    },
    blur: () => {
      gsap.to(focus, { value: 0, duration: 0.4, ease: 'power2.out', overwrite: 'auto' });
    },
  };

  group.userData.interactive = true;
  group.userData.cursor = 'pointer';

  // kept references for cleanup
  const pressPings = [];

  // --- cleanup ---
  group.userData.cleanup = () => {
    pressPings.forEach((t) => t.kill());
    gsap.killTweensOf(plane.position);
    gsap.killTweensOf(plane.scale);
    gsap.killTweensOf(cursorX);
    gsap.killTweensOf(cursorY);
    gsap.killTweensOf(focus);
    gsap.killTweensOf(jewelLight);
    gsap.killTweensOf(rimAccent);
    gsap.killTweensOf(planeMat);

    backdropGeo.dispose();
    backdropMat.dispose();
    planeGeo.dispose();
    planeMat.dispose();

    if (colorTexUniform.value && colorTexUniform.value.dispose) {
      try { colorTexUniform.value.dispose(); } catch (_) {}
    }
    if (depthTexUniform.value && depthTexUniform.value.dispose) {
      try { depthTexUniform.value.dispose(); } catch (_) {}
    }
  };

  return group;
}
